using System;
using System.Collections.Generic;

class Solution
{
    static void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());
        List<string> companies = new List<string>();
        Dictionary<string, int> firewall = new Dictionary<string, int>();

        for (int i = 0; i < n; i++)
        {
            string[] parts = Console.ReadLine().Split(':');
            companies.Add(parts[0]);
            firewall[parts[0]] = int.Parse(parts[1]);
        }

        Dictionary<string, Dictionary<string, int>> attacks = new Dictionary<string, Dictionary<string, int>>();
        foreach (string name in companies)
        {
            attacks[name] = new Dictionary<string, int>
            {
                { "ps", 0 },
                { "bf", 0 },
                { "mi", 0 }
            };
        }

        int a = int.Parse(Console.ReadLine());
        for (int i = 0; i < a; i++)
        {
            string[] parts = Console.ReadLine().Split(':');
            string name = parts[0];
            string type = parts[1];
            int strength = int.Parse(parts[2]);

            if (attacks.ContainsKey(name) && attacks[name].ContainsKey(type))
            {
                attacks[name][type] += strength;
            }
        }

        foreach (string name in companies)
        {
            int p = firewall[name];
            int ps = attacks[name]["ps"];
            int bf = attacks[name]["bf"];
            int mi = attacks[name]["mi"];

            bool hacked = false;

            if (p >= 7)
            {
                hacked = false;
            }
            else if (p >= 5)
            {
                if (bf >= 5000 && mi >= 3000)
                {
                    hacked = true;
                }
            }
            else
            {
                if (bf >= 500 && mi >= 1000)
                {
                    hacked = true;
                }
            }

            Console.WriteLine($"{name}:{(hacked ? "Hacked" : "Blocked")}");
        }
    }
}
